const entry=`import * as THREE from 'three';import {OrbitControls} from 'three/examples/jsm/controls/OrbitControls.js';import {GLTFLoader} from 'three/examples/jsm/loaders/GLTFLoader.js';
const canvas=document.querySelector('canvas'),renderer=new THREE.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0xf4f7f6);const world=new THREE.Scene(),camera=new THREE.PerspectiveCamera(36,1,0.001,20),controls=new OrbitControls(camera,canvas);controls.enableDamping=true;world.add(new THREE.HemisphereLight(0xffffff,0x53616a,2.3));const key=new THREE.DirectionalLight(0xffffff,2.5);key.position.set(2,3,4);world.add(key);const meshes=[];let loaded=false;const select=document.querySelector('select'),label=document.querySelector('#selection');
const model=await new GLTFLoader().loadAsync('/model.glb');world.add(model.scene);model.scene.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.userData.originalMaterial=o.material.clone();o.userData.sourceName=model.parser.json.meshes[model.parser.associations.get(o)?.meshes]?.name??o.name.replaceAll('_',' ');meshes.push(o);const option=document.createElement('option');option.value=o.uuid;option.textContent=o.userData.sourceName;select.append(option);}});const box=new THREE.Box3().setFromObject(model.scene),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),radius=Math.max(size.x,size.y,size.z)*1.65;controls.target.copy(center);
function view(axis){camera.position.copy(center).add(new THREE.Vector3(...axis).normalize().multiplyScalar(radius));camera.lookAt(center);controls.update();}view([0.7,0.25,1]);
function selection(){const id=select.value;for(const m of meshes){const core=m.userData.sourceName.startsWith('Limb orientation core');m.visible=!core||document.querySelector('#context').checked;m.material.transparent=core||Boolean(id&&m.uuid!==id);m.material.opacity=core?0.12:id&&m.uuid!==id?0.07:1;m.material.depthWrite=!(core||id&&m.uuid!==id);}const m=meshes.find(m=>m.uuid===id);label.textContent=m?m.userData.sourceName+' · '+m.geometry.getAttribute('position').count+' source vertices':'All 26 original source meshes';}select.addEventListener('change',selection);document.querySelector('#context').addEventListener('change',selection);selection();document.querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>view(JSON.parse(b.dataset.axis)));
const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down;canvas.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY]});canvas.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>4)return;const b=canvas.getBoundingClientRect();pointer.set((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(meshes.filter(m=>m.visible&&!m.userData.sourceName.startsWith('Limb orientation core')),false)[0];if(hit){select.value=hit.object.uuid;selection();}});
function resize(){const b=canvas.parentElement.getBoundingClientRect();renderer.setSize(b.width,b.height,false);camera.aspect=b.width/b.height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(canvas.parentElement);resize();loaded=true;document.querySelector('#status').textContent='Loaded original GLB; technical visual screen only';window.sourceScreen={get status(){return {loaded,meshes:meshes.length,sourceBounds:{min:box.min.toArray(),max:box.max.toArray()},selection:label.textContent,renderer:renderer.info.render,contextLost:renderer.getContext().isContextLost()}}};renderer.setAnimationLoop(()=>{controls.update();renderer.render(world,camera)});`;
const require=createRequire(native+'/package.json');await require('esbuild').build({stdin:{contents:entry,resolveDir:native,loader:'js'},bundle:true,platform:'browser',format:'esm',outfile:base+'/screen.js',minify:false,define:{'process.env.NODE_ENV':'"production"'}});
const html='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unadmitted leg nerve source screen</title><style>body{margin:0;font:14px system-ui;color:#153b3c;background:#f4f7f6}header{padding:14px 22px;background:#e3eeea}header h1{font-size:21px;margin:0 0 6px}header p{margin:4px 0}main{display:grid;grid-template-columns:minmax(0,1fr) 300px;height:calc(100dvh - 130px)}.stage{min-width:0;position:relative}canvas{width:100%;height:100%;display:block}aside{padding:18px;background:white;overflow:auto}label{display:grid;gap:8px;margin-bottom:18px}select,button{font:inherit;padding:8px;max-width:100%}button{margin:5px}#selection{overflow-wrap:anywhere}#status{font-size:12px}a{color:#00645e}</style></head><body><header><h1>Lower-limb nerve source study — unadmitted</h1><p>Publisher labels this an original CC0 model. Names, left side, nerve courses and source units require review.</p><p>No Atlas-body or patient-space registration. Orientation core is illustrative context, not validated bone or muscle anatomy.</p></header><main><div class="stage"><canvas aria-label="Original lower-limb nerve source model"></canvas></div><aside><label>Original source mesh<select><option value="">All source meshes</option></select></label><label><span><input id="context" type="checkbox" checked> Show translucent orientation core</span></label><div><button data-axis="[0,0,1]">+Z view</button><button data-axis="[1,0,0]">+X view</button><button data-axis="[0,0,-1]">−Z view</button><button data-axis="[0.7,0.25,1]">Oblique</button></div><p id="selection"></p><p id="status">Loading local candidate…</p><p>Rotate: drag. Zoom: wheel. Select a source mesh in the list or by clicking.</p><p><a href="https://www.innerscene.com/tools/library/3d-parts/leg-nerves-60edf433" target="_blank" rel="noreferrer">Publisher and asset licence declaration</a></p></aside></main><script type="module" src="/screen.js"></script></body></html>';
const routes=new Map([['/',()=>['text/html',html]],['/screen.js',()=>['text/javascript',fs.readFileSync(base+'/screen.js')]],['/model.glb',()=>{assert.equal(hash(asset),sha);return['model/gltf-binary',fs.readFileSync(asset)]}]]);
