const handle={at:new Date().toISOString(),pid:process.pid,port,url:'http://127.0.0.1:'+port+'/',source:{path:asset,sha256:sha},unadmitted:true,normalPreviewChanged:false};fs.writeFileSync(base+'/HANDLE.json',JSON.stringify(handle,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(handle));process.stdin.setEncoding('utf8');process.stdin.on('data',text=>{if(text.trim()==='stop'){server.close(()=>{fs.writeFileSync(base+'/TERMINAL.json',JSON.stringify({at:new Date().toISOString(),pid:process.pid,cooperativeShutdown:true})+'\n',{flag:'wx'});process.exit(0)});server.closeIdleConnections()}});process.stdin.resume();
